INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'O Leão que Tinha Medo do Escuro', N'Narrativo', 1, N'5 min', N'🦁', N'🌙🦁🌳', N'Era uma vez um <strong class="palavra-chave">leão</strong> chamado <strong class="palavra-chave">Léo</strong>. Ele morava numa <strong class="palavra-chave">floresta</strong> verde e bonita. Léo era grande e forte. Todo mundo achava que ele não tinha medo de nada. Mas Léo tinha um segredo… De <strong class="palavra-chave">dia</strong>, Léo brincava com os amigos. Ele corria, pulava e rugia bem alto. Mas quando o <strong class="palavra-chave">sol</strong> ia embora, Léo ficava quietinho. A noite chegava. O escuro chegava. E Léo corria se esconder atrás de uma pedra grande. Os amigos perguntavam: "Léo, onde você está?" A <strong class="palavra-chave">zebra</strong>, o <strong class="palavra-chave">elefante</strong> e o <strong class="palavra-chave">macaco</strong> procuravam por ele. Léo não respondia. Ele fechava os olhos e esperava o dia voltar. Uma noite, a <strong class="palavra-chave">lua</strong> apareceu bem grande no céu. Ela disse com voz mansa: "Léo, não tenha medo! Eu fico aqui com você toda noite." Léo olhou para o céu. Viu a lua brilhando. Viu as estrelas piscando. E sorriu. Dali em diante, Léo não tinha mais medo. Toda noite ele olhava para a lua e se sentia <strong class="palavra-chave">corajoso</strong>. Ele chamava os amigos para brincar à luz das estrelas. A noite virou a hora favorita de Léo!', N'["leão", "floresta", "noite", "lua", "corajoso"]', N'{"idOriginal": "n1", "fases": [{"texto": "Era uma vez um <strong class=\"palavra-chave\">leão</strong> chamado <strong class=\"palavra-chave\">Léo</strong>. Ele morava numa <strong class=\"palavra-chave\">floresta</strong> verde e bonita. Léo era grande e forte. Todo mundo achava que ele não tinha medo de nada. Mas Léo tinha um segredo…"}, {"texto": "De <strong class=\"palavra-chave\">dia</strong>, Léo brincava com os amigos. Ele corria, pulava e rugia bem alto. Mas quando o <strong class=\"palavra-chave\">sol</strong> ia embora, Léo ficava quietinho. A noite chegava. O escuro chegava. E Léo corria se esconder atrás de uma pedra grande."}, {"texto": "Os amigos perguntavam: \"Léo, onde você está?\" A <strong class=\"palavra-chave\">zebra</strong>, o <strong class=\"palavra-chave\">elefante</strong> e o <strong class=\"palavra-chave\">macaco</strong> procuravam por ele. Léo não respondia. Ele fechava os olhos e esperava o dia voltar."}, {"texto": "Uma noite, a <strong class=\"palavra-chave\">lua</strong> apareceu bem grande no céu. Ela disse com voz mansa: \"Léo, não tenha medo! Eu fico aqui com você toda noite.\" Léo olhou para o céu. Viu a lua brilhando. Viu as estrelas piscando. E sorriu."}, {"texto": "Dali em diante, Léo não tinha mais medo. Toda noite ele olhava para a lua e se sentia <strong class=\"palavra-chave\">corajoso</strong>. Ele chamava os amigos para brincar à luz das estrelas. A noite virou a hora favorita de Léo!"}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'A Menina que Colecionava Nuvens', N'Narrativo', 2, N'8 min', N'☁️', N'☁️👧🌈', N'Marina tinha um hobby que ninguém mais tinha: ela <strong class="palavra-chave">colecionava nuvens</strong>. Não as nuvens de verdade, claro — essas não dá para guardar numa caixa. Marina colecionava os <strong class="palavra-chave">desenhos</strong> dela. Toda manhã, antes do café, ela corria para a janela do seu quarto e ficava olhando o céu por alguns minutos. Se a nuvem tinha um formato interessante, ela pegava o caderno azul e desenhava com cuidado. Já eram mais de cem desenhos. Cada um tinha um nome diferente, escolhido por ela. Havia a nuvem "Baleia Voadora", a "Bota do Gigante" e até uma chamada "Avó Dormindo". Os colegas da escola achavam graça. "Nuvens? Mas elas somem!", diziam. Marina só dava de ombros. Ela sabia que justamente por isso eram especiais: cada nuvem existia <strong class="palavra-chave">uma única vez</strong>. Nenhuma voltava igual. Numa terça-feira de outubro, uma nuvem diferente de todas apareceu no céu. Era enorme, escura nas bordas, mas com o centro branco e brilhante. E o formato… era de um <strong class="palavra-chave">dragão</strong>. Tinha pescoço longo, asas abertas e até o que parecia ser fogo saindo da boca. Marina ficou paralisada. Era a nuvem mais incrível que ela já tinha visto. Ela correu para pegar o caderno — mas quando voltou, a nuvem já estava mudando. O pescoço virou uma colina. As asas viraram ondas. Marina sentiu um aperto no peito. Então lembrou: o celular! Ela fotografou o que restava da nuvem-dragão. Não era perfeito, mas dava para ver um pouco das asas ainda abertas. Um mês depois, Marina olhou pela janela e não acreditou: o <strong class="palavra-chave">dragão</strong> tinha voltado! Igual. Com pescoço longo, asas e tudo. Ela correu com o caderno e dessa vez desenhou tudo, com calma. E no mês seguinte, voltou de novo. E no outro também. Marina descobriu que aquela nuvem aparecia sempre que o vento vinha do sul. Ela deu um nome para ela: <strong class="palavra-chave">Fogo</strong>. E toda vez que Fogo aparecia, Marina sabia: ia ser um dia especial!', N'["colecionava", "nuvens", "desenhos", "dragão", "Fogo"]', N'{"idOriginal": "n2", "fases": [{"texto": "Marina tinha um hobby que ninguém mais tinha: ela <strong class=\"palavra-chave\">colecionava nuvens</strong>. Não as nuvens de verdade, claro — essas não dá para guardar numa caixa. Marina colecionava os <strong class=\"palavra-chave\">desenhos</strong> dela. Toda manhã, antes do café, ela corria para a janela do seu quarto e ficava olhando o céu por alguns minutos. Se a nuvem tinha um formato interessante, ela pegava o caderno azul e desenhava com cuidado. Já eram mais de cem desenhos. Cada um tinha um nome diferente, escolhido por ela."}, {"texto": "Havia a nuvem \"Baleia Voadora\", a \"Bota do Gigante\" e até uma chamada \"Avó Dormindo\". Os colegas da escola achavam graça. \"Nuvens? Mas elas somem!\", diziam. Marina só dava de ombros. Ela sabia que justamente por isso eram especiais: cada nuvem existia <strong class=\"palavra-chave\">uma única vez</strong>. Nenhuma voltava igual."}, {"texto": "Numa terça-feira de outubro, uma nuvem diferente de todas apareceu no céu. Era enorme, escura nas bordas, mas com o centro branco e brilhante. E o formato… era de um <strong class=\"palavra-chave\">dragão</strong>. Tinha pescoço longo, asas abertas e até o que parecia ser fogo saindo da boca. Marina ficou paralisada. Era a nuvem mais incrível que ela já tinha visto."}, {"texto": "Ela correu para pegar o caderno — mas quando voltou, a nuvem já estava mudando. O pescoço virou uma colina. As asas viraram ondas. Marina sentiu um aperto no peito. Então lembrou: o celular! Ela fotografou o que restava da nuvem-dragão. Não era perfeito, mas dava para ver um pouco das asas ainda abertas."}, {"texto": "Um mês depois, Marina olhou pela janela e não acreditou: o <strong class=\"palavra-chave\">dragão</strong> tinha voltado! Igual. Com pescoço longo, asas e tudo. Ela correu com o caderno e dessa vez desenhou tudo, com calma. E no mês seguinte, voltou de novo. E no outro também. Marina descobriu que aquela nuvem aparecia sempre que o vento vinha do sul. Ela deu um nome para ela: <strong class=\"palavra-chave\">Fogo</strong>. E toda vez que Fogo aparecia, Marina sabia: ia ser um dia especial."}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'O Guardião da Biblioteca Secreta', N'Narrativo', 3, N'12 min', N'📚', N'📚🔑🏛️', N'Pedro tinha o hábito de não prestar atenção nas coisas. Não por descuido, exatamente — era mais uma questão de <strong class="palavra-chave">escolha</strong>. O mundo tinha partes interessantes e partes que não valiam o espaço, e Pedro achava que sabia muito bem distinguir uma coisa da outra. A porta marrom no fundo do corredor da escola, por exemplo, claramente pertencia à segunda categoria. Era velha, sem plaquinha, sem maçaneta especial. Provavelmente um depósito de vassouras. Ele tinha passado por ela centenas de vezes sem pestanejar. Até aquela quinta-feira. Pedro voltava da aula de ciências com a cabeça ainda cheia de perguntas que o professor não soubera responder — ou não quisera. Ao passar pelo corredor, percebeu algo diferente: a porta estava <strong class="palavra-chave">entreaberta</strong>. Uma fresta fina. E por ela vazava uma luz que não era de lâmpada. Era dourada demais. Quente demais. Pedro parou. Olhou para os dois lados do corredor. Não havia ninguém. Ele empurrou a porta devagar. O que havia do outro lado não cabia na lógica de um depósito de vassouras. Era uma <strong class="palavra-chave">biblioteca enorme</strong> — alta demais para caber num prédio térreo, larga demais para estar dentro da escola. As prateleiras iam do chão ao teto e se curvavam levemente, como se o cômodo fosse redondo. E os livros brilhavam. Não todos — mas muitos tinham um leve pulsar de luz na lombada, como se respirassem. Pedro sentiu que deveria ter medo. Mas o que sentiu foi outra coisa: <strong class="palavra-chave">reconhecimento</strong>. Como se aquele lugar já o esperasse há tempo. "Você demorou." A voz veio de algum lugar entre as prateleiras. Pedro deu um passo atrás — mas não saiu. Uma <strong class="palavra-chave">raposa</strong> surgiu caminhando devagar, óculos de aros dourados equilibrados na ponta do focinho, um livro aberto na pata esquerda. Ela se sentou numa cadeira de veludo vermelho como se aquilo fosse a coisa mais natural do mundo. "Cada guardião demora um tempo diferente para encontrar a biblioteca", ela disse. "Alguns levam dias. Outros, anos. Você levou três." Pedro abriu a boca. "Três o quê?" "Anos de escola", respondeu a raposa, virando uma página. A raposa explicou com a paciência de quem já explicou a mesma coisa muitas vezes — e ainda assim não achava a explicação cansativa. Cada livro naquela biblioteca guardava uma <strong class="palavra-chave">história verdadeira</strong>: não necessariamente um fato histórico, mas algo que havia sido sentido de verdade por alguém, em algum lugar, em algum tempo. "Histórias verdadeiras precisam ser lidas", ela disse. "Quando ninguém lê, elas enfraquecem. A lombada perde o brilho. E quando o brilho some de vez…" Ela fechou o livro com cuidado. "A história desaparece. Como se nunca tivesse acontecido." Pedro passou aquela tarde inteira na biblioteca. Leu sobre uma <strong class="palavra-chave">civilização</strong> que construía cidades nas copas das árvores e desapareceu antes de ser descoberta. Leu o diário de uma menina que vivia numa estação espacial e sentia saudade da chuva. Leu a história de um urso que tinha aprendido a escrever sozinho e deixado cartas escondidas em ocos de árvores pela floresta. Cada livro tinha um brilho diferente. Alguns pulsavam devagar, como coração em repouso. Outros tremiam um pouco, como se tivessem pressa de ser lidos. Quando saiu, o corredor estava vazio e as luzes da escola já tinham sido apagadas. Pedro ficou parado diante da porta marrom, agora fechada de novo. Entendeu, naquele momento, o que a raposa quis dizer. Ser <strong class="palavra-chave">guardião</strong> não era uma tarefa de vigia — não era trancar a biblioteca, catalogar os livros, protegê-los do pó. Era outra coisa, mais difícil e mais simples ao mesmo tempo: era carregar as histórias dentro de si. Lembrar delas. Deixar que mudassem alguma coisa. Porque uma história só existe de verdade quando alguém a leva para fora da página.', N'["biblioteca", "guardião", "reconhecimento", "civilização", "histórias"]', N'{"idOriginal": "n3", "fases": [{"texto": "Pedro tinha o hábito de não prestar atenção nas coisas. Não por descuido, exatamente — era mais uma questão de <strong class=\"palavra-chave\">escolha</strong>. O mundo tinha partes interessantes e partes que não valiam o espaço, e Pedro achava que sabia muito bem distinguir uma coisa da outra. A porta marrom no fundo do corredor da escola, por exemplo, claramente pertencia à segunda categoria. Era velha, sem plaquinha, sem maçaneta especial. Provavelmente um depósito de vassouras. Ele tinha passado por ela centenas de vezes sem pestanejar."}, {"texto": "Até aquela quinta-feira. Pedro voltava da aula de ciências com a cabeça ainda cheia de perguntas que o professor não soubera responder — ou não quisera. Ao passar pelo corredor, percebeu algo diferente: a porta estava <strong class=\"palavra-chave\">entreaberta</strong>. Uma fresta fina. E por ela vazava uma luz que não era de lâmpada. Era dourada demais. Quente demais. Pedro parou. Olhou para os dois lados do corredor. Não havia ninguém. Ele empurrou a porta devagar."}, {"texto": "O que havia do outro lado não cabia na lógica de um depósito de vassouras. Era uma <strong class=\"palavra-chave\">biblioteca enorme</strong> — alta demais para caber num prédio térreo, larga demais para estar dentro da escola. As prateleiras iam do chão ao teto e se curvavam levemente, como se o cômodo fosse redondo. E os livros brilhavam. Não todos — mas muitos tinham um leve pulsar de luz na lombada, como se respirassem. Pedro sentiu que deveria ter medo. Mas o que sentiu foi outra coisa: <strong class=\"palavra-chave\">reconhecimento</strong>. Como se aquele lugar já o esperasse há tempo."}, {"texto": "\"Você demorou.\" A voz veio de algum lugar entre as prateleiras. Pedro deu um passo atrás — mas não saiu. Uma <strong class=\"palavra-chave\">raposa</strong> surgiu caminhando devagar, óculos de aros dourados equilibrados na ponta do focinho, um livro aberto na pata esquerda. Ela se sentou numa cadeira de veludo vermelho como se aquilo fosse a coisa mais natural do mundo. \"Cada guardião demora um tempo diferente para encontrar a biblioteca\", ela disse. \"Alguns levam dias. Outros, anos. Você levou três.\" Pedro abriu a boca. \"Três o quê?\" \"Anos de escola\", respondeu a raposa, virando uma página."}, {"texto": "A raposa explicou com a paciência de quem já explicou a mesma coisa muitas vezes — e ainda assim não achava a explicação cansativa. Cada livro naquela biblioteca guardava uma <strong class=\"palavra-chave\">história verdadeira</strong>: não necessariamente um fato histórico, mas algo que havia sido sentido de verdade por alguém, em algum lugar, em algum tempo. \"Histórias verdadeiras precisam ser lidas\", ela disse. \"Quando ninguém lê, elas enfraquecem. A lombada perde o brilho. E quando o brilho some de vez…\" Ela fechou o livro com cuidado. \"A história desaparece. Como se nunca tivesse acontecido.\""}, {"texto": "Pedro passou aquela tarde inteira na biblioteca. Leu sobre uma <strong class=\"palavra-chave\">civilização</strong> que construía cidades nas copas das árvores e desapareceu antes de ser descoberta. Leu o diário de uma menina que vivia numa estação espacial e sentia saudade da chuva. Leu a história de um urso que tinha aprendido a escrever sozinho e deixado cartas escondidas em ocos de árvores pela floresta. Cada livro tinha um brilho diferente. Alguns pulsavam devagar, como coração em repouso. Outros tremiam um pouco, como se tivessem pressa de ser lidos."}, {"texto": "Quando saiu, o corredor estava vazio e as luzes da escola já tinham sido apagadas. Pedro ficou parado diante da porta marrom, agora fechada de novo. Entendeu, naquele momento, o que a raposa quis dizer. Ser <strong class=\"palavra-chave\">guardião</strong> não era uma tarefa de vigia — não era trancar a biblioteca, catalogar os livros, protegê-los do pó. Era outra coisa, mais difícil e mais simples ao mesmo tempo: era carregar as histórias dentro de si. Lembrar delas. Deixar que mudassem alguma coisa. Porque uma história só existe de verdade quando alguém a leva para fora da página."}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'A Chuva Cantando', N'Poetico', 1, N'4 min', N'🌧️', N'🌧️🌈☂️', N'<em>"Pingo, pingo, pinguinho,<br>a chuva veio sim!<br>Molhou o passarinho,<br>molhou o meu jardim."</em> <em>"Pingo, pingo, pinguinho,<br>que gostoso é assim!<br>A chuva faz barulho:<br>tim-tim, tim-tim, tim-tim!"</em> <em>"E eu de guarda-chuva,<br>saí para brincar!<br>Com poça lá na rua,<br>que gostoso pular!"</em> <em>"Pingo, pingo, pinguinho,<br>não para, não, não!<br>A chuva é minha amiga,<br>vem, chuva, venha cá!"</em>', N'["pingo", "chuva", "passarinho", "jardim", "poça"]', N'{"idOriginal": "p1", "fases": [{"texto": "<em>\"Pingo, pingo, pinguinho,<br>a chuva veio sim!<br>Molhou o passarinho,<br>molhou o meu jardim.\"</em>"}, {"texto": "<em>\"Pingo, pingo, pinguinho,<br>que gostoso é assim!<br>A chuva faz barulho:<br>tim-tim, tim-tim, tim-tim!\"</em>"}, {"texto": "<em>\"E eu de guarda-chuva,<br>saí para brincar!<br>Com poça lá na rua,<br>que gostoso pular!\"</em>"}, {"texto": "<em>\"Pingo, pingo, pinguinho,<br>não para, não, não!<br>A chuva é minha amiga,<br>vem, chuva, venha cá!\"</em>"}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'Palavras que Voam', N'Poetico', 2, N'6 min', N'🦋', N'🦋🌸📜', N'<em>"Palavras são pássaros<br> que moram no papel,<br> guardam segredos doces<br> mais doces que o mel."<br></em> <em>"Quando você as lê,<br> elas ganham asas,<br> atravessam a noite<br> e chegam nas casas."<br></em> <em>"Há palavras mansas<br> que chegam de mansinho,<br> como luz de vela<br> no fim do caminho."<br></em> <em>"Há palavras bravas<br> que saltam do chão,<br> e batem no peito<br> feito coração."<br></em> <em>"Guarda bem as tuas,<br>escolhe com cuidado —<br>uma palavra dita<br> não volta ao seu lado."<br></em>', N'["palavras", "pássaros", "papel", "asas", "segredos"]', N'{"idOriginal": "p2", "fases": [{"texto": "<em>\"Palavras são pássaros<br> que moram no papel,<br> guardam segredos doces<br> mais doces que o mel.\"<br></em>"}, {"texto": "<em> \"Quando você as lê,<br> elas ganham asas,<br> atravessam a noite<br> e chegam nas casas.\"<br></em>"}, {"texto": "<em>\"Há palavras mansas<br> que chegam de mansinho,<br> como luz de vela<br> no fim do caminho.\"<br></em>"}, {"texto": "<em>\"Há palavras bravas<br> que saltam do chão,<br> e batem no peito<br> feito coração.\"<br></em>"}, {"texto": "<em>\"Guarda bem as tuas,<br>escolhe com cuidado —<br>uma palavra dita<br> não volta ao seu lado.\"<br></em>"}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'Como Fazer uma Casinha para Pássaros', N'Instrucional', 1, N'6 min', N'🏡', N'🐦🏠🔨', N'Você vai precisar de: uma caixa de <strong class="palavra-chave">sapato</strong>, tinta colorida, palitos de madeira e cola. Essa casinha vai ser um lar aconchegante para os pássaros do jardim! Passo 1: Pinte a caixa com cores vivas. Passo 2: Cole os <strong class="palavra-chave">palitos</strong> na entrada para fazer o poleiro. Passo 3: Faça um buraco na frente com o tamanho certo para o pássaro entrar!', N'["sapato", "palitos", "pinte", "buraco", "poleiro"]', N'{"idOriginal": "i1", "fases": [{"texto": "Você vai precisar de: uma caixa de <strong class=\"palavra-chave\">sapato</strong>, tinta colorida, palitos de madeira e cola. Essa casinha vai ser um lar aconchegante para os pássaros do jardim!"}, {"texto": "Passo 1: Pinte a caixa com cores vivas. Passo 2: Cole os <strong class=\"palavra-chave\">palitos</strong> na entrada para fazer o poleiro. Passo 3: Faça um buraco na frente com o tamanho certo para o pássaro entrar!"}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'Receita: Cápsula do Tempo', N'Instrucional', 3, N'16 min', N'🟢', N'🧪🟢✋', N'Existem objetos que não guardam apenas coisas, mas guardam versões inteiras de nós mesmos. A <strong class="palavra-chave">cápsula do tempo</strong> é um desses objetos: um recipiente selado, enterrado ou escondido, criado com o propósito deliberado de ser reaberto apenas no futuro, por uma pessoa que, tecnicamente, ainda não existe — porque quem a abrirá já não será exatamente quem a fechou. Construir uma cápsula do tempo é, portanto, um exercício instrucional com dimensões que vão muito além da simples organização de objetos: é um diálogo silencioso entre o presente e um futuro incerto, uma carta escrita para alguém que carrega o mesmo nome, mas talvez não os mesmos medos, os mesmos sonhos, ou as mesmas certezas. <strong class="palavra-chave">Materiais necessários</strong>: um recipiente resistente e à prova d''água — pode ser uma caixa metálica, um pote de vidro hermético ou um tubo de PVC vedado nas extremidades —, papel e caneta para cartas e listas, fotografias reveladas ou impressas, pequenos objetos de valor simbólico e não apenas material, fita adesiva resistente ou lacre, e uma etiqueta ou placa onde constará a data de fechamento e a data planejada para a reabertura. Antes de reunir qualquer item, porém, é preciso reunir algo mais difícil de encontrar: a disposição para olhar para si mesmo com honestidade. <strong class="palavra-chave">Modo de preparo, primeira etapa — a escrita</strong>: comece escrevendo uma carta para a pessoa que você será quando a cápsula for reaberta. Não escreva apenas sobre fatos — quais escolas você frequentou, quais times você torce, quais músicas você ouve —, mas escreva também sobre aquilo que é mais difícil de nomear: o que você teme perder, o que você espera se tornar, e o que, neste exato momento, você gostaria que seu eu futuro jamais esquecesse de si mesmo. É comum que, no meio da escrita, surjam dúvidas sobre pertencimento: a quem eu pertenço agora? A este grupo de amigos, a esta cidade, a esta versão de mim que ainda está sendo moldada? Essas dúvidas não precisam de resposta imediata; elas apenas precisam ser registradas, como sementes plantadas para uma colheita distante. <strong class="palavra-chave">Segunda etapa — a seleção</strong>: escolha entre três e cinco objetos que representem, de forma simbólica, este período da sua vida. Evite escolher apenas o que é bonito ou o que impressiona; escolha também aquilo que carrega alguma <strong class="palavra-chave">ambiguidade emocional</strong> — um ingresso de um evento em que você se sentiu, ao mesmo tempo, feliz e solitário; um desenho malfeito, mas feito com dedicação; um bilhete de alguém que talvez já não faça mais parte da sua vida do jeito que fazia antes. São justamente esses objetos imperfeitos, carregados de contradição, que melhor contam a verdade sobre quem fomos. <strong class="palavra-chave">Terceira etapa — o fechamento</strong>: organize todos os itens dentro do recipiente, revisando-os uma última vez antes de guardá-los, como quem se despede de uma versão de si mesmo sabendo que, embora ela deixe de existir no presente, continuará existindo ali, suspensa no tempo, esperando. Vede o recipiente cuidadosamente, certificando-se de que não haverá infiltração de água, umidade ou insetos. Anote, na etiqueta externa, a data exata do fechamento e uma data futura para a reabertura — pode ser um ano, cinco anos, ou até uma data ligada a um marco importante, como a formatura ou um aniversário significativo. <strong class="palavra-chave">Quarta etapa — o esconderijo ou enterro</strong>: escolha um local seguro, que provavelmente não sofrerá grandes alterações estruturais no período determinado. Se optar por enterrar a cápsula, marque o local com um ponto de referência discreto, mas memorável — a raiz de uma árvore, a distância de determinados passos a partir de um muro. Se preferir guardá-la em casa, escolha um espaço que não seja mexido com frequência, como o fundo de um armário raramente aberto. Existe algo profundamente simbólico neste ato de esconder: é reconhecer que certas partes de nós precisam de tempo, escuridão e distância para serem verdadeiramente compreendidas — assim como uma fotografia antiga revela detalhes que passaram despercebidos no instante em que foi tirada, mas que se tornam visíveis apenas quando observados de longe. Quando, finalmente, o dia da reabertura chegar, é provável que a pessoa que destacar o lacre já não reconheça completamente a caligrafia daquela carta, os gostos daqueles objetos, ou até mesmo os medos que pareciam, no passado, tão urgentes e definitivos. E é exatamente nesse estranhamento que reside o verdadeiro valor da cápsula do tempo: ela não existe para provar que nada mudou, mas para testemunhar, com honestidade e ternura, tudo aquilo que mudou — e tudo aquilo que, de alguma forma secreta e persistente, continuou sendo, desde sempre, essencialmente você.', N'["cápsula do tempo", "pertencimento", "ambiguidade emocional", "simbólico", "identidade"]', N'{"idOriginal": "i2", "fases": [{"texto": "Existem objetos que não guardam apenas coisas, mas guardam versões inteiras de nós mesmos. A <strong class=\"palavra-chave\">cápsula do tempo</strong> é um desses objetos: um recipiente selado, enterrado ou escondido, criado com o propósito deliberado de ser reaberto apenas no futuro, por uma pessoa que, tecnicamente, ainda não existe — porque quem a abrirá já não será exatamente quem a fechou. Construir uma cápsula do tempo é, portanto, um exercício instrucional com dimensões que vão muito além da simples organização de objetos: é um diálogo silencioso entre o presente e um futuro incerto, uma carta escrita para alguém que carrega o mesmo nome, mas talvez não os mesmos medos, os mesmos sonhos, ou as mesmas certezas."}, {"texto": "<strong class=\"palavra-chave\">Materiais necessários</strong>: um recipiente resistente e à prova d''água — pode ser uma caixa metálica, um pote de vidro hermético ou um tubo de PVC vedado nas extremidades —, papel e caneta para cartas e listas, fotografias reveladas ou impressas, pequenos objetos de valor simbólico e não apenas material, fita adesiva resistente ou lacre, e uma etiqueta ou placa onde constará a data de fechamento e a data planejada para a reabertura. Antes de reunir qualquer item, porém, é preciso reunir algo mais difícil de encontrar: a disposição para olhar para si mesmo com honestidade."}, {"texto": "Modo de preparo, primeira etapa — a escrita: comece escrevendo uma carta para a pessoa que você será quando a cápsula for reaberta. Não escreva apenas sobre fatos, mas escreva também sobre aquilo que é mais difícil de nomear: o que você teme perder, o que você espera se tornar, e o que, neste exato momento, você gostaria que seu eu futuro jamais esquecesse de si mesmo. É comum que, no meio da escrita, surjam dúvidas sobre pertencimento: a quem eu pertenço agora? Essas dúvidas não precisam de resposta imediata; elas apenas precisam ser registradas, como sementes plantadas para uma colheita distante."}, {"texto": "Segunda etapa — a seleção: escolha entre três e cinco objetos que representem, de forma simbólica, este período da sua vida. Evite escolher apenas o que é bonito ou o que impressiona; escolha também aquilo que carrega alguma ambiguidade emocional — um ingresso de um evento em que você se sentiu, ao mesmo tempo, feliz e solitário; um desenho malfeito, mas feito com dedicação; um bilhete de alguém que talvez já não faça mais parte da sua vida do jeito que fazia antes. São justamente esses objetos imperfeitos, carregados de contradição, que melhor contam a verdade sobre quem fomos."}, {"texto": "Terceira etapa — o fechamento: organize todos os itens dentro do recipiente, revisando-os uma última vez antes de guardá-los, como quem se despede de uma versão de si mesmo sabendo que, embora ela deixe de existir no presente, continuará existindo ali, suspensa no tempo, esperando. Vede o recipiente cuidadosamente, certificando-se de que não haverá infiltração de água, umidade ou insetos. Anote, na etiqueta externa, a data exata do fechamento e uma data futura para a reabertura."}, {"texto": "Quarta etapa — o esconderijo ou enterro: escolha um local seguro, que provavelmente não sofrerá grandes alterações estruturais no período determinado. Existe algo profundamente simbólico neste ato de esconder: é reconhecer que certas partes de nós precisam de tempo, escuridão e distância para serem verdadeiramente compreendidas. Quando, finalmente, o dia da reabertura chegar, é provável que a pessoa que destacar o lacre já não reconheça completamente a caligrafia daquela carta, os gostos daqueles objetos, ou até mesmo os medos que pareciam, no passado, tão urgentes e definitivos. E é exatamente nesse estranhamento que reside o verdadeiro valor da cápsula do tempo: ela não existe para provar que nada mudou, mas para testemunhar, com honestidade e ternura, tudo aquilo que mudou — e tudo aquilo que, de alguma forma secreta e persistente, continuou sendo, desde sempre, essencialmente você."}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'O Fundo do Mar Encantado', N'Descritivo', 2, N'7 min', N'🌊', N'🐠🌊🐙', N'O fundo do mar é um mundo à parte — um lugar que poucos olhos já viram de verdade, mas que existe cheio de vida bem abaixo das ondas. A primeira coisa que chama atenção é a <strong class="palavra-chave">luz</strong>: ela chega filtrada pela água, formando raios dourados e tremidos que iluminam tudo como lanternas gigantes balançando no teto. Logo se vê o conjunto de <strong class="palavra-chave">cores vibrantes</strong> que cobre o fundo. Corais <strong class="palavra-chave">laranja e rosa</strong> crescem em formas curiosas — alguns parecem árvores, outros parecem leques abertos, outros ainda parecem cérebros de pedra. Juntos, formam verdadeiras florestas subaquáticas, com suas próprias ruas, esquinas e esconderijos. Entre os corais, peixes de todas as formas dançam sem parar. Alguns são listrados de preto e branco, outros têm manchas amarelas e azuis que parecem pintadas à mão. As algas verdes e compridas balançam suavemente na corrente, como se ouvissem uma música que só elas conhecem. Tudo ali se move — nada fica completamente parado. No chão do oceano, o ritmo é outro. Estrelas-do-mar de cor <strong class="palavra-chave">avermelhada</strong> caminham devagar sobre a areia branca, como se tivessem todo o tempo do mundo. Polvos curiosos esticam seus <strong class="palavra-chave">tentáculos</strong> para explorar conchas, pedras e frestas escuras. De vez em quando, uma nuvem de areia sobe do fundo — sinal de que algum ser passou por ali e preferiu não ser visto. O fundo do mar não tem som da forma que conhecemos — mas não é silêncioso. Há o rangido suave dos corais, o farfalhar das algas, o movimento constante da água. É um <strong class="palavra-chave">silêncio cheio</strong>, como o de uma biblioteca grande onde todos estão muito ocupados. Quem mergulha fundo o suficiente entende: o mar não está vazio. Ele só guarda seus segredos com muito cuidado.', N'["cores", "corais", "vibrantes", "avermelhada", "tentáculos"]', N'{"idOriginal": "d1", "fases": [{"texto": "O fundo do mar é um mundo à parte — um lugar que poucos olhos já viram de verdade, mas que existe cheio de vida bem abaixo das ondas. A primeira coisa que chama atenção é a <strong class=\"palavra-chave\">luz</strong>: ela chega filtrada pela água, formando raios dourados e tremidos que iluminam tudo como lanternas gigantes balançando no teto."}, {"texto": "Logo se vê o conjunto de <strong class=\"palavra-chave\">cores vibrantes</strong> que cobre o fundo. Corais <strong class=\"palavra-chave\">laranja e rosa</strong> crescem em formas curiosas — alguns parecem árvores, outros parecem leques abertos, outros ainda parecem cérebros de pedra. Juntos, formam verdadeiras florestas subaquáticas, com suas próprias ruas, esquinas e esconderijos."}, {"texto": "Entre os corais, peixes de todas as formas dançam sem parar. Alguns são listrados de preto e branco, outros têm manchas amarelas e azuis que parecem pintadas à mão. As algas verdes e compridas balançam suavemente na corrente, como se ouvissem uma música que só elas conhecem. Tudo ali se move — nada fica completamente parado."}, {"texto": "No chão do oceano, o ritmo é outro. Estrelas-do-mar de cor <strong class=\"palavra-chave\">avermelhada</strong> caminham devagar sobre a areia branca, como se tivessem todo o tempo do mundo. Polvos curiosos esticam seus <strong class=\"palavra-chave\">tentáculos</strong> para explorar conchas, pedras e frestas escuras. De vez em quando, uma nuvem de areia sobe do fundo — sinal de que algum ser passou por ali e preferiu não ser visto."}, {"texto": "O fundo do mar não tem som da forma que conhecemos — mas não é silêncioso. Há o rangido suave dos corais, o farfalhar das algas, o movimento constante da água. É um <strong class=\"palavra-chave\">silêncio cheio</strong>, como o de uma biblioteca grande onde todos estão muito ocupados. Quem mergulha fundo o suficiente entende: o mar não está vazio. Ele só guarda seus segredos com muito cuidado."}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'O Jardim da Vovó', N'Descritivo', 1, N'5 min', N'🌻', N'🌻🌹🦋', N'O jardim da <strong class="palavra-chave">vovó</strong> é cheio de flores! Tem rosas <strong class="palavra-chave">vermelhas</strong>, margaridas brancas e girassóis altos e amarelos. As cores são lindas! O cheiro é muito <strong class="palavra-chave">gostoso</strong>. As <strong class="palavra-chave">borboletas</strong> adoram esse jardim. Elas pousam nas flores e ficam quietinhas. Os passarinhos também vêm por aqui. Eles cantam alto e alegram o jardim todo. No meio do jardim tem um <strong class="palavra-chave">banco de madeira</strong>. Ele é velho e tem tinta descascada. A vovó senta ali toda tarde. Ela toma chá e fica olhando as flores. É o lugar mais <strong class="palavra-chave">tranquilo</strong> do mundo!', N'["vovó", "vermelhas", "gostoso", "banco", "tranquilo"]', N'{"idOriginal": "d2", "fases": [{"texto": "O jardim da <strong class=\"palavra-chave\">vovó</strong> é cheio de flores! Tem rosas <strong class=\"palavra-chave\">vermelhas</strong>, margaridas brancas e girassóis altos e amarelos. As cores são lindas! O cheiro é muito <strong class=\"palavra-chave\">gostoso</strong>."}, {"texto": "As <strong class=\"palavra-chave\">borboletas</strong> adoram esse jardim. Elas pousam nas flores e ficam quietinhas. Os passarinhos também vêm por aqui. Eles cantam alto e alegram o jardim todo."}, {"texto": "No meio do jardim tem um <strong class=\"palavra-chave\">banco de madeira</strong>. Ele é velho e tem tinta descascada. A vovó senta ali toda tarde. Ela toma chá e fica olhando as flores. É o lugar mais <strong class=\"palavra-chave\">tranquilo</strong> do mundo!"}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'Por Que o Céu é Azul?', N'Informativo', 2, N'10 min', N'🔵', N'☀️🔵🌍', N'A luz do <strong class="palavra-chave">Sol</strong> parece branca, mas na verdade é formada por todas as cores do arco-íris, misturadas em um só brilho. Se pudéssemos separar essa luz, veríamos vermelho, laranja, amarelo, verde, azul, anil e violeta, todos grudadinhos uns nos outros. Quando essa luz branca sai do Sol, ela viaja por milhões de quilômetros até chegar perto da Terra. Nesse caminho, ela atravessa a <strong class="palavra-chave">atmosfera</strong>, uma camada de ar que envolve todo o planeta como um cobertor invisível. Dentro dessa camada existem bilhões de partículas de ar, tão pequenas que nenhum olho humano consegue enxergá-las sozinhas. Essas partículas estão sempre em movimento, e quando a luz do Sol passa perto delas, algo interessante acontece: cada cor da luz reage de um jeito diferente. As <strong class="palavra-chave">ondas de luz</strong> podem ser curtas ou longas, e isso muda como elas se comportam. A luz vermelha e a luz amarela têm ondas mais longas, então atravessam o ar quase sem serem incomodadas pelas partículas. Já a cor <strong class="palavra-chave">azul</strong> tem uma onda bem curtinha e saltitante, o que faz com que ela seja espalhada para todos os lados quando encontra as partículas de ar. Esse fenômeno é chamado de espalhamento de luz. Como a luz azul se espalha muito mais do que as outras cores, ela acaba preenchendo todo o céu, em todas as direções. Por isso, não importa se olhamos para cima, para os lados ou para longe no horizonte: durante o dia, o céu sempre aparece pintado de azul. Ao entardecer, esse efeito muda um pouco. Quando o Sol está baixo, próximo do horizonte, sua luz precisa atravessar uma camada de atmosfera ainda maior para chegar até nós. Nesse percurso mais longo, quase toda a luz azul já foi espalhada para outros lugares do céu, e as cores que sobram para os nossos olhos são o laranja e o vermelho, criando aqueles pores do sol tão bonitos. À noite, a Terra gira e o Sol fica escondido do outro lado do planeta. Sem a luz solar atravessando a atmosfera, não há mais luz para ser espalhada pelas partículas de ar. O céu perde sua cor azul e fica escuro, permitindo que enxerguemos as estrelas, a Lua e até outros planetas brilhando ao longe. Esse ciclo se repete todos os dias: o céu azul pela manhã, as cores quentes do entardecer e a escuridão da noite, tudo por causa da forma como a luz do Sol interage com as partículas da nossa atmosfera.', N'["Sol", "atmosfera", "luz", "azul", "estrelas"]', N'{"idOriginal": "inf1", "fases": [{"texto": "A luz do <strong class=\"palavra-chave\">Sol</strong> parece branca, mas na verdade é formada por todas as cores do arco-íris, misturadas em um só brilho. Se pudéssemos separar essa luz, veríamos vermelho, laranja, amarelo, verde, azul, anil e violeta, todos grudadinhos uns nos outros. Quando essa luz branca sai do Sol, ela viaja por milhões de quilômetros até chegar perto da Terra. Nesse caminho, ela atravessa a <strong class=\"palavra-chave\">atmosfera</strong>, uma camada de ar que envolve todo o planeta como um cobertor invisível. Dentro dessa camada existem bilhões de partículas de ar, tão pequenas que nenhum olho humano consegue enxergá-las sozinhas."}, {"texto": "Essas partículas estão sempre em movimento, e quando a luz do Sol passa perto delas, algo interessante acontece: cada cor da luz reage de um jeito diferente. As <strong class=\"palavra-chave\">ondas de luz</strong> podem ser curtas ou longas, e isso muda como elas se comportam. A luz vermelha e a luz amarela têm ondas mais longas, então atravessam o ar quase sem serem incomodadas pelas partículas. Já a cor <strong class=\"palavra-chave\">azul</strong> tem uma onda bem curtinha e saltitante, o que faz com que ela seja espalhada para todos os lados quando encontra as partículas de ar. Esse fenômeno é chamado de espalhamento de luz. Como a luz azul se espalha muito mais do que as outras cores, ela acaba preenchendo todo o céu, em todas as direções. Por isso, não importa se olhamos para cima, para os lados ou para longe no horizonte: durante o dia, o céu sempre aparece pintado de azul."}, {"texto": "Ao entardecer, esse efeito muda um pouco. Quando o Sol está baixo, próximo do horizonte, sua luz precisa atravessar uma camada de atmosfera ainda maior para chegar até nós. Nesse percurso mais longo, quase toda a luz azul já foi espalhada para outros lugares do céu, e as cores que sobram para os nossos olhos são o laranja e o vermelho, criando aqueles pores do sol tão bonitos. À noite, a Terra gira e o Sol fica escondido do outro lado do planeta. Sem a luz solar atravessando a atmosfera, não há mais luz para ser espalhada pelas partículas de ar. O céu perde sua cor azul e fica escuro, permitindo que enxerguemos as estrelas, a Lua e até outros planetas brilhando ao longe. Esse ciclo se repete todos os dias: o céu azul pela manhã, as cores quentes do entardecer e a escuridão da noite, tudo por causa da forma como a luz do Sol interage com as partículas da nossa atmosfera."}]}');
GO

INSERT INTO Historia (Origem, Titulo, Genero, FaixaEtaria, Duracao, Emoji, Cena, TextoHtml, PalavrasChaveJson, PayloadJson)
VALUES ('manual', N'Amazônia: O Pulmão do Mundo', N'Informativo', 3, N'12 min', N'🌿', N'🌳🦜🌊', N'A <strong class="palavra-chave">Floresta Amazônica</strong> é a maior floresta tropical do planeta. Ela cobre cerca de 5,5 milhões de km² e abrange nove países, sendo o Brasil o de maior extensão. Estima-se que ela abriga mais de 10% de todas as espécies de animais e plantas da Terra. A Amazônia é chamada de "pulmão do mundo" porque suas árvores absorvem grandes quantidades de <strong class="palavra-chave">dióxido de carbono</strong> e liberam <strong class="palavra-chave">oxigênio</strong>. Isso ajuda a equilibrar o clima do planeta inteiro. Preservar a Amazônia é responsabilidade de todos. O <strong class="palavra-chave">desmatamento</strong> ameaça milhares de espécies e afeta o regime de chuvas de todo o Brasil. Pequenas ações como consumo consciente e apoio a projetos ambientais fazem diferença.', N'["Amazônica", "oxigênio", "desmatamento", "espécies", "clima"]', N'{"idOriginal": "inf2", "fases": [{"texto": "A <strong class=\"palavra-chave\">Floresta Amazônica</strong> é a maior floresta tropical do planeta. Ela cobre cerca de 5,5 milhões de km² e abrange nove países, sendo o Brasil o de maior extensão. Estima-se que ela abriga mais de 10% de todas as espécies de animais e plantas da Terra."}, {"texto": "A Amazônia é chamada de \"pulmão do mundo\" porque suas árvores absorvem grandes quantidades de <strong class=\"palavra-chave\">dióxido de carbono</strong> e liberam <strong class=\"palavra-chave\">oxigênio</strong>. Isso ajuda a equilibrar o clima do planeta inteiro."}, {"texto": "Preservar a Amazônia é responsabilidade de todos. O <strong class=\"palavra-chave\">desmatamento</strong> ameaça milhares de espécies e afeta o regime de chuvas de todo o Brasil. Pequenas ações como consumo consciente e apoio a projetos ambientais fazem diferença."}]}');
GO